"""Build Batch18 audit staging only; no network/database writes."""
from pathlib import Path
from datetime import datetime,timezone
import csv,hashlib,html,json,re
import duckdb
from school_pipeline.approach_migration import validate_records
P=Path('outputs/approach_county_review');B=P/'batch18_10schools_20261030';S=B/'sources';D='2026-10-30'
assert not (B/'Approach_evidence.staged.json').exists()
def dump(n,v): (B/n).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def text(n):
 s=(S/(n+'.html')).read_text();s=re.sub(r'<(script|style)\b.*?</\1>','',s,flags=re.S);return ' '.join(html.unescape(re.sub('<[^>]+>',' ',s)).split())
def title(n):return html.unescape(re.search(r'<title[^>]*>(.*?)</title>',(S/(n+'.html')).read_text(),re.S|re.I)[1]).strip()
u={'roslag':'https://www.norrtalje.se/info/barn-och-skola/grundskola/grundskolor/roslagsskolan/','magelung':'https://grundskola.stockholm/hitta-grundskola/grundskola/magelungsskolan','taby':'https://tabyfriskola.se/','enhagen':'https://tabyfriskola.se/taby-friskola-enhagen/','vaxmora':'https://www.sollentuna.se/uweb/vaxmoraskolan/om-oss/','vaxmora_health':'https://www.sollentuna.se/uweb/vaxmoraskolan/sa-har-arbetar-vi/halsa-och-miljo/','vaxmora_safety':'https://www.sollentuna.se/uweb/vaxmoraskolan/sa-har-arbetar-vi/trygghet-och-studiero/vart-arbete--mot-mobbning/','grisslehamn':'https://www.norrtalje.se/info/barn-och-skola/grundskola/grundskolor/grisslehamns-skola/var-skola/','mortvik':'https://www.huddinge.se/mortviksskolan','mortvik_about':'https://www.huddinge.se/mortviksskolan/om-skolan','nobla':'https://noblaskolan.se/saltsjo-boo/','nobla_language':'https://noblaskolan.se/saltsjo-boo/sprakprofil/','ursvik':'https://www.sundbyberg.se/forskola-skola-och-utbildning/grundskola/grundskolor/ursvikskolan','munso':'https://www.ekero.se/forskola-skola/grundskola/skolor-i-ekero-kommun/munso-skola-f-3','njupkarr':'https://www.tyreso.se/forskola--skola/skolbarn/alla-grundskolor/njupkarrs-skola.html'}
e=[];c=[]
def add(sid,n,q,note,cat=None,sub=None,level='Explicit',confidence='High'):
 assert q in text(n),(sid,n,q)
 eid=f'ae_b18_{sid}_{1+sum(x["school_id"]==sid for x in e):02}'
 e.append(dict(evidence_id=eid,school_id=sid,source_url=u[n],page_title=title(n),accessed_date=D,quoted_text=q,evidence_type='School/provider self-description',interpretation_note=note))
 if cat:
  c.append(dict(code_id=f'ac_b18_{sid}_{1+sum(x["school_id"]==sid for x in c):02}',school_id=sid,category=cat,subcategory=sub,coding_level=level,confidence=confidence,evidence_id=eid,coder_note='Assistant contextual review, codebook v1, 2026-10-30. '+note+' Public claim, not independently verified practice.',review_status='Reviewed'))
add('31851256','roslag','Skolan har även en etablerad musikprofil med en musikklass i varje årskurs.','Music classes in years 7–9, not all pupils; distinct from Roslagens kulturskola.','Arts and creative learning','Music-profile classes')
add('31903219','magelung','Singapore Math i samtliga årskurser','Named subject-specific mathematics method in municipal Farsta F–6 school; not Magelungens Södermalm. Not whole-school alternative pedagogy.','Other stated profile','Singapore Math')
add('32231541','enhagen','På Täby Friskola Enhagen erbjuder vi en Matematikprofil som riktar sig till dig som har ett extra stort intresse för matematik och som tycker det är kul med utmanande matematikuppgifter.','Optional interest-based profile at current Enhagen6–9. Official DB name Täby Friskola; directory ledger Enhagen; unit page matches grades. Future autumn2027 F–9 expansion excluded.','Other stated profile','Mathematics profile')
add('32479095','vaxmora_health','Vi arbetar för att öka rörelse och fysisk aktivitet för en hållbar livsstil. Idrott och hälsa är viktigt för oss på Vaxmoraskolan.','Health/movement emphasis; page says profile permeates subjects. Do not endorse claimed health/results effects. Year5 ice safety/year6 kayaking are scoped activities, not separate outdoor pedagogy.','Support, inclusion, or wellbeing emphasis','Health and movement profile')
add('32479095','vaxmora_safety','Alla kommunala skolor i Sollentuna arbetar utifrån Olweusprogrammet.','Municipality-wide policy on local page. Do not create another distinctive code from compulsory anti-bullying work; not independent implementation evidence.')
add('32585503','grisslehamn','Skolan har en egen orkester där många av eleverna medverkar. Orkestern tränar en gång i veckan under skoltid.','Recurring school-time orchestra plus instrument learning; participation is many, not all pupils. Supported music emphasis, not explicit whole-school music profile.','Arts and creative learning','Recurring school orchestra','Supported','Medium')
add('32585503','grisslehamn','Vi arbetar ofta kring ett temaområde, där vi försöker integrera så många ämnen som möjligt.','Theme-based integration alone does not establish inquiry/project method. Nearby environment used for learning but insufficient specific outdoor teaching detail; no extra code.')
add('32886383','mortvik_about','Naturen och skolans utemiljöer är en naturlig del av vardagen och bidrar till lek, rörelse och gemensamma upplevelser.','Unclear/Low note only: repeated outdoor descriptions mix school/fritids, play and movement; no clearly specified outdoor instructional method. Requires review if stronger source emerges.')
add('32965692','nobla','Vi har även en språkprofil som genomsyrar hela vår verksamhet, från förskolan upp till årskurs 9.','Explicit local language profile; school1–9 joined to official ID, preschool out of analytical scope. Detail page describes rhetoric, Nordic collaboration and upper-grade exchanges; opportunities/plans not guaranteed participation or verified delivery.','Language, international, or intercultural profile','Language profile')
add('32965692','nobla_language','Från årskurs 7 erbjuder vi en spännande språkkurs i ett nytt europeiskt språk, till exempel italienska.','Upper-grade-specific description supports language profile; not all grades or bilingual instruction. Erasmus funding/participation claims not verified.')
add('32993837','ursvik','Vår verksamhet bygger på en stark värdegrund där respekt, ansvar och samarbete är centralt.','Scoped no clear approach evidence in school page: vision, organisation, fritids, safety/support read. Generic values and ordinary support not distinctive; nature proximity not outdoor method. Not absence of an approach.')
add('33159363','munso','För att vi ska utveckla vårt förhållningsätt utgår vi från Dr. Ross W. Greenes verktyg CPS. Det är verktyg för samarbetsbaserad problemlösning.','Explicit CPS relationship/problem-solving approach on Munsö F–3 page. Page also introduces SAM preschool organisation; scope not independently verified; do not extend to all SAM units.','Support, inclusion, or wellbeing emphasis','Collaborative problem solving (CPS)')
add('33455004','njupkarr','På Njupkärrs skola visar vi våra elever världen genom upplevelsebaserat lärande, utflykter och museibesök samt genom olika teman.','Explicit experience-based learning with excursions/museums/themes; no evidence of inquiry/project process, so Other stated profile. Current pavilion, not planned new building.','Other stated profile','Experience-based learning')
validate_records(e,c)
selection=json.loads((P/'next_batch_after_batch17.json').read_text());assert len(selection)==10
con=duckdb.connect('.state/schools.duckdb',read_only=True)
meta={r[0]:dict(zip(['school_id','name','municipality_code','grades_json','website'],r)) for r in con.execute('select school_unit_code,name,municipality_code,grades_json,website from schools').fetchall()};con.close()
scopes={'31851256':'Music classes7–9 only.','31903219':'Farsta municipalF–6; official1–6. Current200 supersedes inaccessible historical status; Stockholm robots control-byte uncertainty.','32231541':'Current Enhagen6–9; official DB name Täby Friskola vs ledger Täby Friskola-Enhagen.2027 F–9 expansion excluded.','32479095':'F–6 vs official1–6; current official URL200 replaces old registered edu.sollentuna URL; no assumption about old URL status.','32585503':'SchoolF–6 vs official1–6; orchestra participants only.','32886383':'SchoolF–6; regional F–9 is not local provision. Nature-school/fritids scope unclear.','32965692':'School1–9; preschool excluded; upper-grade detail scoped.','32993837':'Current schoolF–6; old registered URL not tested; successful current official source supersedes inaccessible historical classification.','33159363':'SchoolF–3; official1–3. SAM preschool context retained; precise CPS implementation not independently verified.','33455004':'F–6 vs official1–6; existing pavilion separate from future school.'}
review=[];logs=[]
for row in selection:
 sid=row['school_id'];names=sorted({x['source_url'] for x in e if x['school_id']==sid});nc=sum(x['school_id']==sid for x in c);out='Reviewed claim' if nc else ('Unclear evidence; requires review' if sid=='32886383' else 'Scoped no clear evidence')
 review.append(dict(school_id=sid,school_name=row['official_directory_name'],outcome=out,evidence_count=sum(x['school_id']==sid for x in e),code_count=nc,unit_scope=scopes[sid],follow_up=scopes[sid] if sid in ['31903219','32231541','32886383','33159363'] else 'No additional unit identity question; claims remain unverified.',reviewer='Assistant contextual review; not independent verification',accessed_date=D,load_state='Staged, not loaded'))
 for n,url in u.items():
  if url in names or (sid=='32231541' and n=='taby') or (sid=='32479095' and n=='vaxmora') or (sid=='32886383' and n=='mortvik'):
   logs.append(dict(school_id=sid,registered_url=row['registered_url'],selected_url=url,page_title=title(n),accessed_date=D,status=200,saved_file='sources/'+n+'.html',selection_rationale='Official school/provider page matching school name and grade context; current official page preferred over historical root/obsolete URL.',scope=scopes[sid],outcome=out,exclusions='No login/application/admin/social/children-gallery collection; generic results claims, ordinary subject lists and future provision excluded. Full HTML is raw transport capture and can include site contacts; no employee personal data extracted into analytical tables.',permissions='Robots files saved. No relevant disallow found; Stockholm malformed/control bytes unresolved. No general licence inferred. Linked legal terms not exhaustively reviewed; short attributed quotations only. Policy checks occurred after initial collection, not preflight clearance.'))
dump('selection.json',selection);dump('official_selection_metadata.json',[meta[x['school_id']] for x in selection]);dump('Approach_evidence.staged.json',e);dump('Approach_codes.staged.json',c)
with (B/'review_log.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=review[0].keys());w.writeheader();w.writerows(review)
(B/'collection_log.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in logs))
dump('source_manifest.json',[dict(file=f.name,bytes=f.stat().st_size,sha256=hashlib.sha256(f.read_bytes()).hexdigest()) for f in sorted(S.iterdir()) if f.is_file()])
dump('validation.json',dict(schema_valid=True,exact_quote_matches=len(e),quote_match_scope='Each quotation matched normalized text of its own saved source, not a different page.',evidence=len(e),codes=len(c),schools=len(selection),validated_at=datetime.now(timezone.utc).isoformat(),source_access_date_basis='Public fetches recorded in active task on2026-10-30, not page-update or load date.',caveats=['Robots checks after initial fetches','Stockholm robots control-byte uncertainty','Terms not exhaustively reviewed','No inferred county representativeness']))
(B/'decision_log.md').write_text('''# Batch18 decisions —2026-10-30\nAssistant contextual review; codebook v1 unchanged. Claims, not verified practice.\n- Roslagsskolan: local7–9 music classes; not Roslagens kulturskola.\n- Magelung: named Singapore Math -> Other stated profile; subject-specific, not alternative whole-school pedagogy. Municipal Farsta, not Magelungen Södermalm.\n- Enhagen: optional mathematics profile; preserve name discrepancy; future2027 expansion excluded.\n- Vaxmora: explicit health profile. Olweus municipality policy noted, not an extra distinctive code. No causal results endorsement.\n- Grisslehamn: recurring weekly school orchestra -> Supported/Medium arts; not all pupils. Theme integration alone insufficient for project/inquiry. Nature-use description insufficient for separate firm outdoor code.\n- Mörtvik: uncertain outdoor evidence remains uncoded; school/fritids scope unresolved.\n- Nobla: explicit language profile; preschool excluded; exchange opportunities/year scopes retained.\n- Ursvik: scoped review of vision, organisation, fritids and support found no distinctive approach evidence; not proof of absence.\n- Munsö: named CPS -> support/inclusion; SAM context disclosed, no extension to other units.\n- Njupkärr: explicit experience-based learning -> Other; not automatically inquiry/project or outdoor pedagogy.\n\nSearch/review concepts: om oss/about us, pedagogik/pedagogy, undervisning/education, profil/profile, kreativ/creative, estetisk/arts, lärande/learning, värdegrund/values. Concepts guide contextual reading; not claims that each was separately queried.\nPermissions: nine robots files saved after initial page collection; Stockholm malformed control bytes remain uncertain. Other policies contain no relevant disallow. Täby requests10s delay; no subsequent Täby requests made. Terms/licensing not exhaustively reviewed. No control bypass; only short quotes republished. Raw captures may contain staff contact navigation; none extracted to evidence.\n''')
(B/'REPORT.md').write_text('# Batch18 school-approach review\n\n10 schools selected in ascending official-ID order from pending ledger. '+str(len(e))+' evidence records / '+str(len(c))+' codes staged. Eight schools have reviewed claims, Mörtvik uncertain/uncoded, Ursvik scoped no-clear-evidence. Source claims are not verified teaching practice; this is not a representative county sample.\n\nSee review_log.csv, decision_log.md, collection_log.jsonl and validation.json. Staging is not loading; ledger remains unchanged pending append/replay.\n')
dump('batch_status.json',dict(status='STAGED_VALIDATED_NOT_LOADED',schools=10,evidence=len(e),codes=len(c),date=D))
print(json.dumps(dict(evidence=len(e),codes=len(c),schools=10)))
